begin; do $test$ declare uid uuid:=gen_random_uuid(); begin insert into auth.users(id,email,raw_user_meta_data,created_at) values(uid,'backend-profile-test-'||uid||'@example.invalid','{}',now()); perform set_config('test.profile_id',uid::text,true); end $test$; set local role service_role; do $test$ declare uid uuid:=current_setting('test.profile_id')::uuid; begin if private.seller_in_creation() or private.profile_in_edit() then raise exception 'Unexpected write context'; end if; update public.profiles set full_name='Backend profile save regression' where id=uid; if not exists(select 1 from public.profiles where id=uid and full_name='Backend profile save regression') then raise exception 'Backend profile save failed'; end if; if has_function_privilege('anon','private.seller_in_creation()','execute') or has_function_privilege('anon','private.profile_in_edit()','execute') then raise exception 'Anonymous access granted'; end if; end $test$; select 'PASS: administrative backend profile save works and anonymous context access stays denied' result; rollback;